"""Characters of the two structures: Kleene stars, exponentials, divided powers.

This demonstration checks, with exact rational arithmetic:

  * that the Kleene star of a plane, l*(x_1...x_n) = c_1...c_n, is a character for
    concatenation, f(uv) = f(u)f(v), and is *not* a character for the shuffle
    unless the plane vanishes;
  * that the exponential of a plane, exp(l)(x_1...x_n) = c_1...c_n / n!, is a
    character for the shuffle, f(u)f(v) = sum over the shuffles of f;
  * the divided-power identity f(a^n) = f(a)^n / n!, valid for *every* shuffle
    character, verified here on exponentials and violated by Kleene stars;
  * that the infinitesimal characters for concatenation, i.e. the linear forms
    with g(uv) = g(u)eps(v) + eps(u)g(v), are exactly the planes.
"""

from __future__ import annotations

from collections import Counter
from fractions import Fraction
from itertools import product
from math import factorial
from typing import Callable, Dict, List, Tuple

Word = Tuple[str, ...]


def shuffle(u: Word, v: Word) -> Counter:
    if not u:
        return Counter({v: 1})
    if not v:
        return Counter({u: 1})
    out: Counter = Counter()
    for z, m in shuffle(u[1:], v).items():
        out[(u[0],) + z] += m
    for z, m in shuffle(u, v[1:]).items():
        out[(v[0],) + z] += m
    return out


def words_upto(alphabet: str, depth: int) -> List[Word]:
    out: List[Word] = []
    for n in range(depth + 1):
        out.extend(product(tuple(alphabet), repeat=n))
    return out


def plane_star(c: Dict[str, Fraction]) -> Callable[[Word], Fraction]:
    def f(w: Word) -> Fraction:
        out = Fraction(1)
        for a in w:
            out *= c[a]
        return out
    return f


def exp_plane(c: Dict[str, Fraction]) -> Callable[[Word], Fraction]:
    def f(w: Word) -> Fraction:
        out = Fraction(1)
        for a in w:
            out *= c[a]
        return out / factorial(len(w))
    return f


def is_concat_character(f: Callable[[Word], Fraction], words: List[Word]) -> bool:
    return f(()) == 1 and all(f(u + v) == f(u) * f(v) for u in words for v in words)


def is_shuffle_character(f: Callable[[Word], Fraction], words: List[Word]) -> bool:
    if f(()) != 1:
        return False
    for u in words:
        for v in words:
            rhs = sum((Fraction(m) * f(z) for z, m in shuffle(u, v).items()), Fraction(0))
            if f(u) * f(v) != rhs:
                return False
    return True


def main() -> None:
    c = {"a": Fraction(3, 2), "b": Fraction(-2)}
    words = words_upto("ab", 2)
    star, expo = plane_star(c), exp_plane(c)

    print("plane  l = (3/2)a - 2b")
    print(f"  l*  is a concatenation character : {is_concat_character(star, words)}")
    print(f"  l*  is a shuffle character       : {is_shuffle_character(star, words)}")
    print(f"  e^l is a shuffle character       : {is_shuffle_character(expo, words)}")
    print(f"  e^l is a concatenation character : {is_concat_character(expo, words)}")

    print("\ndivided powers  f(a^n) = f(a)^n / n!")
    print(f"{'n':>3} {'exp(l)(a^n)':>18} {'f(a)^n/n!':>18} {'l*(a^n)':>12}")
    for n in range(7):
        an = ("a",) * n
        print(f"{n:>3} {str(expo(an)):>18} {str(expo(('a',)) ** n / factorial(n)):>18} "
              f"{str(star(an)):>12}")

    print("\nthe two character families meet only at the counit:")
    zero = {"a": Fraction(0), "b": Fraction(0)}
    both = plane_star(zero)
    print(f"  l = 0: l* = counit, concatenation character {is_concat_character(both, words)}, "
          f"shuffle character {is_shuffle_character(both, words)}")

    print("\ninfinitesimal characters for concatenation are exactly the planes:")

    def counit(w: Word) -> Fraction:
        return Fraction(1) if not w else Fraction(0)

    def is_inf_char(g: Callable[[Word], Fraction]) -> bool:
        return all(g(u + v) == g(u) * counit(v) + counit(u) * g(v)
                   for u in words for v in words)

    plane = lambda w: {("a",): Fraction(5), ("b",): Fraction(-1)}.get(w, Fraction(0))
    deg2 = lambda w: Fraction(1) if w == ("a", "b") else Fraction(0)
    const = lambda w: Fraction(1)
    print(f"  g = 5a - b            (a plane)        : {is_inf_char(plane)}")
    print(f"  g = ab                (degree two)     : {is_inf_char(deg2)}")
    print(f"  g = 1 on every word   (degree zero)    : {is_inf_char(const)}")


if __name__ == "__main__":
    main()

"""Rationality under the shuffle product, and the Hankel obstruction.

Three things are demonstrated with exact rational arithmetic:

  * the shuffle product of series, (f sh g)(w) = sum over the splittings
    (u,v) of the positions of w of f(u)g(v), extends the shuffle of words;
  * rationality is stable under it: the Hankel ranks of a shuffle product of
    rational series stay bounded, and are bounded by the product of the ranks;
  * the exponential series is the obstruction: its Hankel ranks grow without
    bound, because the factorial Hankel matrix [1/(i+j)!] is nonsingular in
    every size.
"""

from __future__ import annotations

from collections import Counter
from fractions import Fraction
from itertools import product
from math import factorial
from typing import Callable, List, Tuple

Word = Tuple[str, ...]
Series = Callable[[Word], Fraction]


def unshuffle(w: Word) -> Counter:
    if not w:
        return Counter({((), ()): 1})
    a, out = w[0], Counter()
    for (p, q), m in unshuffle(w[1:]).items():
        out[((a,) + p, q)] += m
        out[(p, (a,) + q)] += m
    return out


def shuffle_series(f: Series, g: Series) -> Series:
    def h(w: Word) -> Fraction:
        return sum((Fraction(m) * f(p) * g(q) for (p, q), m in unshuffle(w).items()),
                   Fraction(0))
    return h


def words_upto(alphabet: str, depth: int) -> List[Word]:
    out: List[Word] = []
    for n in range(depth + 1):
        out.extend(product(tuple(alphabet), repeat=n))
    return out


def rank(matrix: List[List[Fraction]]) -> int:
    m = [row[:] for row in matrix]
    rows, cols = len(m), (len(m[0]) if m else 0)
    r = 0
    for c in range(cols):
        piv = next((i for i in range(r, rows) if m[i][c] != 0), None)
        if piv is None:
            continue
        m[r], m[piv] = m[piv], m[r]
        p = m[r][c]
        m[r] = [x / p for x in m[r]]
        for i in range(rows):
            if i != r and m[i][c] != 0:
                fac = m[i][c]
                m[i] = [x - fac * y for x, y in zip(m[i], m[r])]
        r += 1
        if r == rows:
            break
    return r


def hankel_rank(f: Series, alphabet: str, depth: int) -> int:
    ws = words_upto(alphabet, depth)
    return rank([[f(u + v) for v in ws] for u in ws])


def determinant(matrix: List[List[Fraction]]) -> Fraction:
    m = [row[:] for row in matrix]
    n, det = len(m), Fraction(1)
    for c in range(n):
        piv = next((i for i in range(c, n) if m[i][c] != 0), None)
        if piv is None:
            return Fraction(0)
        if piv != c:
            m[c], m[piv] = m[piv], m[c]
            det = -det
        det *= m[c][c]
        inv = m[c][c]
        m[c] = [x / inv for x in m[c]]
        for i in range(c + 1, n):
            if m[i][c] != 0:
                fac = m[i][c]
                m[i] = [x - fac * y for x, y in zip(m[i], m[c])]
    return det


def main() -> None:
    count_a: Series = lambda w: Fraction(sum(1 for a in w if a == "a"))
    count_b: Series = lambda w: Fraction(sum(1 for a in w if a == "b"))
    geom: Series = lambda w: Fraction(3) ** len(w)

    print("Hankel ranks of some rational series (depths 1,2,3 over {a,b}):")
    for name, f in [("|w|_a", count_a), ("|w|_b", count_b), ("3^|w|", geom)]:
        print(f"  {name:>8} : {[hankel_rank(f, 'ab', d) for d in (1, 2, 3)]}")

    print("\nHankel ranks of their shuffle products (bounded, so still rational):")
    for name, f, g in [("|w|_a sh 3^|w|", count_a, geom),
                       ("|w|_a sh |w|_b", count_a, count_b),
                       ("3^|w| sh 3^|w|", geom, geom)]:
        h = shuffle_series(f, g)
        print(f"  {name:>16} : {[hankel_rank(h, 'ab', d) for d in (1, 2, 3)]}")

    print("\nthe shuffle of series extends the shuffle of words:")
    u, v = ("a", "b"), ("a",)
    du: Series = lambda z: Fraction(1) if z == u else Fraction(0)
    dv: Series = lambda z: Fraction(1) if z == v else Fraction(0)
    h = shuffle_series(du, dv)
    for z in words_upto("ab", 3):
        if h(z) != 0:
            print(f"  coefficient at {''.join(z):>4} : {h(z)}")

    print("\nthe exponential obstruction (one-letter alphabet):")
    expo: Series = lambda w: Fraction(1, factorial(len(w)))
    print(f"  Hankel ranks of exp(a) at depths 1..6 : "
          f"{[hankel_rank(expo, 'a', d) for d in range(1, 7)]}")
    print("  leading minors of the factorial Hankel matrix [1/(i+j)!]:")
    for n in range(1, 7):
        M = [[Fraction(1, factorial(i + j)) for j in range(n)] for i in range(n)]
        print(f"    n = {n}: {determinant(M)}")


if __name__ == "__main__":
    main()

