function SHUFFLE(u, v):
    memo <- empty dictionary keyed by (i, j)
    function REC(i, j):                      # suffixes u[i:] and v[j:]
        if (i, j) in memo: return memo[(i, j)]
        if i = |u|: result <- { v[j:] : 1 }
        else if j = |v|: result <- { u[i:] : 1 }
        else:
            result <- empty multiset
            for (z, m) in REC(i+1, j):       # emit the letter u[i] first
                result[u[i] . z] <- result[u[i] . z] + m
            for (z, m) in REC(i, j+1):       # emit the letter v[j] first
                result[v[j] . z] <- result[v[j] . z] + m
        memo[(i, j)] <- result
        return result
    return REC(0, 0)

