"""Memoized enumeration of the shuffle product with multiplicities."""

from __future__ import annotations

from functools import lru_cache
from math import comb
from typing import Dict, Tuple

Word = Tuple[str, ...]


def shuffle_multiplicities(u: Word, v: Word) -> Dict[Word, int]:
    """Return the coefficient vector of u shuffle v.

    The shuffle is defined by the recursion
        1 sh v = v,   u sh 1 = u,
        au sh bv = a (u sh bv) + b (au sh v),
    and is a *multiset*: interleavings arising from different position sets are
    counted separately.  Memoizing on the pair of suffix indices reduces the
    number of distinct recursive calls to (|u|+1)(|v|+1).
    """
    @lru_cache(maxsize=None)
    def rec(i: int, j: int) -> Tuple[Tuple[Word, int], ...]:
        if i == len(u):
            return ((v[j:], 1),)
        if j == len(v):
            return ((u[i:], 1),)
        acc: Dict[Word, int] = {}
        for z, m in rec(i + 1, j):
            key = (u[i],) + z
            acc[key] = acc.get(key, 0) + m
        for z, m in rec(i, j + 1):
            key = (v[j],) + z
            acc[key] = acc.get(key, 0) + m
        return tuple(acc.items())

    return dict(rec(0, 0))


def total_multiplicity(u: Word, v: Word) -> int:
    """Total number of interleavings, which must equal C(|u|+|v|, |u|)."""
    return sum(shuffle_multiplicities(u, v).values())


if __name__ == "__main__":
    u, v = tuple("ab"), tuple("ac")
    for z, m in sorted(shuffle_multiplicities(u, v).items()):
        print(f"{m} x {''.join(z)}")
    print("total:", total_multiplicity(u, v), "= C(4,2) =", comb(4, 2))
    print("a sh a :", shuffle_multiplicities(("a",), ("a",)))

