function HANKEL-RANK(f, alphabet, d):
    W <- all words over alphabet of length <= d, in shortlex order
    H <- matrix with H[u][v] = f(u . v) for u, v in W    # exact rationals
    return RANK(H)

function RANK(M):
    r <- 0
    for each column c:
        find a row i >= r with M[i][c] != 0; if none, continue
        swap rows i and r; scale row r so that M[r][c] = 1
        for every other row i: M[i] <- M[i] - M[i][c] * M[r]
        r <- r + 1
    return r

function CERTIFY(f, alphabet, D):
    ranks <- [ HANKEL-RANK(f, alphabet, d) for d = 1..D ]
    return (ranks[D] = ranks[D-1], ranks)   # stabilised ?

function MINIMAL-REPRESENTATION(f, alphabet, d):
    P <- all words of length <= d       # candidate prefixes
    S <- all words of length <= d       # probing suffixes
    ROW(u) := vector [ f(u . s) : s in S ]

    basis_words <- [], basis_rows <- []
    for u in P in shortlex order:
        if RANK(basis_rows + [ROW(u)]) > RANK(basis_rows):
            append u to basis_words; append ROW(u) to basis_rows
    n <- |basis_words|

    for each letter a in alphabet:
        for i = 1..n:
            mu(a)[i] <- COORDINATES(basis_rows, ROW(basis_words[i] . a))
    lambda <- COORDINATES(basis_rows, ROW(empty word))
    gamma[i] <- f(basis_words[i])
    return (lambda, mu, gamma)

function COORDINATES(basis, target):
    reduce the augmented system [basis | I] to row echelon form
    clear the pivots of target one at a time, accumulating the
    combinations recorded in the identity block
    return the accumulated coefficient vector

postcondition: f(w) = lambda . mu(w) . gamma for every word w

function DECONC-OF-SHUFFLE(u, v):            # left-hand side
    T <- empty multiset of tensors
    for (z, m) in SHUFFLE(u, v):
        for k = 0..|z|:                       # every cut of z
            T[(z[:k], z[k:])] <- T[(z[:k], z[k:])] + m
    return T

function SHUFFLE-OF-DECONC(u, v):            # right-hand side
    T <- empty multiset of tensors
    for (p1, p2) in CUTS(u):
        for (q1, q2) in CUTS(v):
            for (r, m) in SHUFFLE(p1, q1):
                for (s, n) in SHUFFLE(p2, q2):
                    T[(r, s)] <- T[(r, s)] + m * n
    return T

function VERIFY(alphabet, L):
    for all words u, v of length <= L:
        assert DECONC-OF-SHUFFLE(u, v) = SHUFFLE-OF-DECONC(u, v)

duality check: multiplicity of z in SHUFFLE(u,v)
             = multiplicity of (u,v) in UNSHUFFLE(z)

