"""Duality-transport verification of the deconcatenation bialgebra axiom."""

from __future__ import annotations

from collections import Counter
from functools import lru_cache
from itertools import product
from typing import Counter as CounterT, List, Tuple

Word = Tuple[str, ...]
Pair = Tuple[Word, Word]


@lru_cache(maxsize=None)
def shuffle(u: Word, v: Word) -> Tuple[Tuple[Word, int], ...]:
    """The multiset u shuffle v, as a tuple of (word, multiplicity) pairs."""
    if not u:
        return ((v, 1),)
    if not v:
        return ((u, 1),)
    acc: CounterT[Word] = Counter()
    for z, m in shuffle(u[1:], v):
        acc[(u[0],) + z] += m
    for z, m in shuffle(u, v[1:]):
        acc[(v[0],) + z] += m
    return tuple(acc.items())


@lru_cache(maxsize=None)
def unshuffle(w: Word) -> Tuple[Tuple[Pair, int], ...]:
    """The unshuffle coproduct: all splittings of the positions of w."""
    if not w:
        return ((((), ()), 1),)
    a, acc = w[0], Counter()
    for (p, q), m in unshuffle(w[1:]):
        acc[((a,) + p, q)] += m
        acc[(p, (a,) + q)] += m
    return tuple(acc.items())


def deconcat(w: Word) -> List[Pair]:
    """The deconcatenation coproduct: the |w|+1 cuts of w."""
    return [(w[:k], w[k:]) for k in range(len(w) + 1)]


def deconc_of_shuffle(u: Word, v: Word) -> CounterT[Pair]:
    """Left-hand side: apply deconcatenation to every shuffle of u and v."""
    out: CounterT[Pair] = Counter()
    for z, m in shuffle(u, v):
        for pr in deconcat(z):
            out[pr] += m
    return out


def shuffle_of_deconc(u: Word, v: Word) -> CounterT[Pair]:
    """Right-hand side: shuffle the two deconcatenations componentwise."""
    out: CounterT[Pair] = Counter()
    for p1, p2 in deconcat(u):
        for q1, q2 in deconcat(v):
            for r, m in shuffle(p1, q1):
                for s, n in shuffle(p2, q2):
                    out[(r, s)] += m * n
    return out


def duality_holds(u: Word, v: Word, z: Word) -> bool:
    """The multiplicity of z in u shuffle v equals that of (u,v) in unshuffle(z)."""
    lhs = dict(shuffle(u, v)).get(z, 0)
    rhs = dict(unshuffle(z)).get((u, v), 0)
    return lhs == rhs


def verify_axiom(alphabet: str, max_len: int) -> Tuple[int, int]:
    """Check the axiom on all pairs of words of length at most max_len.

    Returns (number of pairs checked, number of counterexamples).  Complexity is
    dominated by the right-hand side, which enumerates (|u|+1)(|v|+1) pairs of
    cuts and, for each, a product of two shuffles.
    """
    words: List[Word] = []
    for n in range(max_len + 1):
        words.extend(product(tuple(alphabet), repeat=n))
    checked = bad = 0
    for u in words:
        for v in words:
            checked += 1
            if deconc_of_shuffle(u, v) != shuffle_of_deconc(u, v):
                bad += 1
    return checked, bad


if __name__ == "__main__":
    checked, bad = verify_axiom("ab", 3)
    print(f"deconcatenation axiom: {checked} pairs checked, {bad} counterexamples")
    words = [(), ("a",), ("a", "b"), ("b", "a"), ("a", "a", "b")]
    ok = all(duality_holds(u, v, z) for u in words for v in words for z in words)
    print("shuffle/unshuffle duality on the sample:", ok)
